import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import Navbar from "@/components/Navbar";
import { Input } from "@/components/ui/input";
import EmptyState from "@/components/EmptyState";
import { ShieldAlert, ShieldCheck } from "lucide-react";
import { track } from "@/lib/analytics";
import { toast } from "@/components/ui/use-toast";
import SEO from "@/components/SEO";

interface ModerationRow {
  id: string;
  video_id: string;
  title: string;
  channel_title: string;
  thumbnail_url: string | null;
  reject_reason: string;
  matched_rule: string | null;
  halal_score: number | null;
  source: string | null;
  created_at: string;
}

const reasonTone: Record<string, "danger" | "warning" | "muted" | "primary" | "gold"> = {
  keyword: "danger",
  female_visual: "danger",
  female_presenter: "danger",
  soft_pattern: "warning",
  emoji: "warning",
  low_score: "muted",
  thumbnail_unsafe: "danger",
};

const ModerationLog = ({ embedded = false }: { embedded?: boolean } = {}) => {
  const { user } = useAuth();
  const [rows, setRows] = useState<ModerationRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [forbidden, setForbidden] = useState(false);
  const [filter, setFilter] = useState("");
  const [reasonFilter, setReasonFilter] = useState<string>("all");

  useEffect(() => {
    if (!user) return;
    track("moderation_log_view");
    (async () => {
      setLoading(true);
      const { data, error } = await supabase
        .from("moderation_log")
        .select("*")
        .order("created_at", { ascending: false })
        .limit(500);
      if (error) {
        setForbidden(true);
        track("moderation_log_load_failed", { error: error.message });
        toast({ title: "Couldn't load moderation log", description: error.message, variant: "destructive" });
      } else {
        const rows = (data ?? []) as ModerationRow[];
        setRows(rows);
        track("moderation_log_loaded", { count: rows.length });
      }
      setLoading(false);
    })();
  }, [user]);

  if (!user) {
    return (
      <div className={embedded ? "" : "min-h-dvh bg-background"}>
        {!embedded && <Navbar />}
        <main className={embedded ? "py-4 text-center" : "container mx-auto px-4 py-16 text-center"}>
          <h1 className="text-title font-bold">Sign in required</h1>
          <p className="mt-2 text-muted-foreground">
            <Link to="/login" className="text-primary underline">Log in</Link> as an admin to view the moderation log.
          </p>
        </main>
      </div>
    );
  }

  const filtered = rows.filter((r) => {
    if (reasonFilter !== "all" && r.reject_reason !== reasonFilter) return false;
    if (!filter) return true;
    const f = filter.toLowerCase();
    return (
      r.title.toLowerCase().includes(f) ||
      r.channel_title.toLowerCase().includes(f) ||
      (r.matched_rule ?? "").toLowerCase().includes(f)
    );
  });

  const reasons = Array.from(new Set(rows.map((r) => r.reject_reason)));

  return (
    <div className={embedded ? "" : "min-h-dvh bg-background"}>
      <SEO title="Moderation Log — Heartify Admin" description="History of moderation decisions across the Heartify platform." path="/admin/moderation-log" />
      {!embedded && <Navbar />}
      <main className={embedded ? "" : "container mx-auto px-4 py-8"}>
        {!embedded && (
          <div className="mb-6 flex items-center gap-3">
            <ShieldAlert className="h-7 w-7 text-primary" />
            <div>
              <h1 className="text-title font-bold">Moderation Log</h1>
              <p className="text-sm text-muted-foreground">
                Videos rejected by the halal filter, with the exact rule that triggered each block.
              </p>
            </div>
          </div>
        )}

        {forbidden && (
          <div className="rounded-card border border-destructive/40 bg-destructive/10 p-4 text-sm">
            You don't have admin access to view the moderation log.
          </div>
        )}

        {!forbidden && (
          <>
            <div className="mb-4 flex flex-wrap gap-2">
              <Input
                placeholder="Search title, channel, or rule…"
                value={filter}
                onChange={(e) => setFilter(e.target.value)}
                className="max-w-sm"
              />
              <select
                value={reasonFilter}
                onChange={(e) => setReasonFilter(e.target.value)}
                className="rounded-card border bg-background px-3 py-2 text-sm"
              >
                <option value="all">All reasons ({rows.length})</option>
                {reasons.map((r) => (
                  <option key={r} value={r}>
                    {r} ({rows.filter((x) => x.reject_reason === r).length})
                  </option>
                ))}
              </select>
            </div>

            {loading ? (
              <p className="text-muted-foreground">Loading…</p>
            ) : filtered.length === 0 ? (
              <EmptyState
                icon={ShieldCheck}
                title="No rejections match"
                description="Either nothing has been auto-rejected under these filters, or the pipeline is running clean. Try widening the search or clearing filters."
              />
            ) : (
              <div className="overflow-x-auto rounded-card border">
                <table className="heartify-table w-full text-sm">
                  <thead>
                    <tr>
                      <th>Thumb</th>
                      <th>Title</th>
                      <th>Channel</th>
                      <th>Reason</th>
                      <th>Matched rule</th>
                      <th>Score</th>
                      <th>Source</th>
                      <th>When</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filtered.map((r) => (
                      <tr key={r.id} tabIndex={0}>
                        <td>
                          {r.thumbnail_url ? (
                            <img src={r.thumbnail_url} alt="" loading="lazy" className="h-12 w-20 rounded object-cover" />
                          ) : null}
                        </td>
                        <td className="max-w-xs truncate font-medium">{r.title}</td>
                        <td className="text-muted-foreground">{r.channel_title}</td>
                        <td>
                          <span className={`heartify-chip heartify-chip--${reasonTone[r.reject_reason] ?? "muted"}`}>
                            {r.reject_reason}
                          </span>
                        </td>
                        <td className="font-mono text-micro">{r.matched_rule ?? "—"}</td>
                        <td>{r.halal_score ?? 0}</td>
                        <td className="text-micro text-muted-foreground">{r.source}</td>
                        <td className="text-micro text-muted-foreground">
                          {new Date(r.created_at).toLocaleString()}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}

          </>
        )}
      </main>
    </div>
  );
};

export default ModerationLog;
